const previewRoot=document.body.classList.contains('style-guide')?'../':'';
const $=(s,scope=document)=>scope.querySelector(s);
const $$=(s,scope=document)=>[...scope.querySelectorAll(s)];
const icon=name=>`<svg class="icon" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const escapeText=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const products={
 express:{name:'Express Pay',tag:'Parking payments',image:'express-pay.webp',description:"Our hero unit offers drivers easy, convenient access from their vehicle, making it the ideal system for most parking needs.",features:['Contactless payment at the exit','Parking sessions linked to number plates','Connected to the Parkezi cloud platform'],url:'https://www.parkezi.com.au/products/express-pay/'},
 step:{name:'Step & Pay',tag:'Pay before you drive',image:'step-pay.webp',description:"An add-on to Express Pay that can be placed in convenient locations like foyers or lift wells, allowing easy prepayment before entering their vehicle.",features:['Convenient on-foot parking payments','Works alongside Express Pay','Designed for a connected parking journey'],url:'https://www.parkezi.com.au/products/step-and-pay/'},
 scan:{name:'Scan & Go',tag:'Vehicle access',image:'scan-go.webp',description:"A self-contained system for simple entry or exit access control, using an ANPR camera to identify whitelisted vehicles.",features:['Automatic number plate recognition','Access for authorised vehicles','Connected access control'],url:'https://www.parkezi.com.au/products/scan-and-go/'},
 mini:{name:'Scan & Go Mini',tag:'Compact access control',image:'scan-go-mini.webp',description:"All the benefits of Scan & Go, but suitable for limited space areas.",features:['Compact camera and control components','Suitable for limited-space locations','Number plate-based access'],url:'https://www.parkezi.com.au/products/scan-and-go-mini/'},
 solar:{name:'SolarGate+',tag:'Portable site access',image:'solargate-open.avif',description:"Portable, Secure & Smart Access Control for Construction, Events, and Industrial Sites",features:['Portable barrier and solar panel','A practical option for temporary sites','Smart access control beyond a fixed entrance'],url:'https://www.parkezi.com.au/products/solargate-mobile-boom-gate/'},
};
const systems={
 paid:{name:'Paid Parking',tag:'Revenue & payments',image:'parking-entry.avif',description:'A connected, ticketless parking system for public and commercial car parks. Link number plate recognition, parking payments and reporting in one setup.',features:['Shopping centres and commercial parking','Hotels and visitor parking','Flexible payment options'],priority:'Paid parking'},
 two:{name:'Two-Way',tag:'Entry & exit control',image:'two-way.avif',description:'Manage vehicle entry and exit around your own access requirements. A starting point for offices, residential buildings and industrial sites.',features:['Authorised vehicle access','Office and residential parking','Site-specific entry and exit rules'],priority:'Private access'},
 one:{name:'One-Way',tag:'Straightforward access',image:'one-way.avif',description:'A straightforward way to manage access for smaller businesses, visitor parking and holiday parks, tailored around how your site operates.',features:['Smaller sites and businesses','Visitor access','Holiday parks and managed entrances'],priority:'Private access'},
};
const projects={
 quest:{name:'Quest Apartments & Northies Hotel',tag:'Hospitality & mixed use',intro:'One car park serves residents, serviced apartments, businesses, staff, hotel guests and the public. Each group needs a different way to access and use the site.',heading:'Different users. One coordinated system.',description:'Parkezi configured access for residents, staff and businesses, alongside parking validation for hotel patrons and paid parking for public visitors. The operator can manage different user groups within the same site.',images:['quest-entry.avif','quest-installation-detail.avif'],url:'https://www.parkezi.com.au/project/quest-apartments/'},
 knight:{name:'Knight Frank Chatswood',tag:'Commercial parking',intro:'Knight Frank wanted a replacement parking system with greater control over visitor access, payments and the service provided to their customers.',heading:'Ticketless payments, directly to the operator.',description:'The Parkezi setup supports pay-on-exit parking, digital receipts and flexible passes for regular customers. Parking revenue goes directly to the operator’s account, with no supplier commission charged in this project.',images:['knight-frank.avif','anpr-camera.avif'],url:'https://www.parkezi.com.au/project/knight-frank-chatswood/'},
};
const dialog=$('#detailDialog');let lastDialogTrigger=null;
function openDialog(content,trigger){lastDialogTrigger=trigger||document.activeElement;$('#dialogContent').innerHTML=content;dialog.showModal();document.body.style.overflow='hidden';}
function closeDialog(){dialog.close();}
$('.dialog-close').addEventListener('click',closeDialog);
dialog.addEventListener('click',e=>{const box=dialog.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)closeDialog();});
dialog.addEventListener('close',()=>{document.body.style.overflow='';if(lastDialogTrigger?.isConnected)lastDialogTrigger.focus({preventScroll:true});});
const featureMarkup=items=>`<ul class="dialog-list">${items.map(t=>`<li>${icon('check')}<span>${t}</span></li>`).join('')}</ul>`;
document.addEventListener('click',e=>{
 const productTrigger=e.target.closest('[data-product]');if(productTrigger){e.preventDefault();const p=products[productTrigger.dataset.product];if(!p)return;if(productTrigger.dataset.product==='express'){window.location.href=previewRoot+'express-pay.html';return;}openDialog(`<article class="preview-scope"><h2 id="dialogTitle">I’ve only done the homepage.</h2><p>Hey Blake, I’ve only done the homepage and one product page. If you wanted to chat about doing the rest, let’s chat.</p><div class="dialog-actions"><a class="button button-dark" href="https://dabhandmarketing.com/book-a-call" target="_blank" rel="noopener noreferrer">Book a call ${icon('arrow')}</a></div></article>`,productTrigger);return;}
 const systemTrigger=e.target.closest('[data-system]');if(systemTrigger){e.preventDefault();const s=systems[systemTrigger.dataset.system];if(!s)return;openDialog(`<article class="preview-scope"><h2 id="dialogTitle">I’ve only done the homepage.</h2><p>Hey Blake, I’ve only done the homepage and one product page. If you wanted to chat about doing the rest, let’s chat.</p><div class="dialog-actions"><a class="button button-dark" href="https://dabhandmarketing.com/book-a-call" target="_blank" rel="noopener noreferrer">Book a call ${icon('arrow')}</a></div></article>`,systemTrigger);return;}
 const projectTrigger=e.target.closest('[data-project]');if(projectTrigger){const p=projects[projectTrigger.dataset.project];openDialog(`<article class="dialog-project"><p class="eyebrow">${p.tag}</p><h2 id="dialogTitle">${p.name}</h2><p>${p.intro}</p><div class="project-detail-images">${p.images.map((im,i)=>`<img src="${previewRoot}assets/${im}" alt="${p.name} ${i?'project detail':'parking site'}">`).join('')}</div><h3>${p.heading}</h3><p>${p.description}</p><div class="dialog-actions"><a class="button button-dark" href="#enquire" data-dialog-enquire>Talk about your project ${icon('arrow')}</a><a class="text-link" href="${p.url}" target="_blank" rel="noopener">Full case study ${icon('chevron')}</a></div></article>`,projectTrigger);return;}
 const enquiryTrigger=e.target.closest('[data-dialog-enquire]');if(enquiryTrigger){e.preventDefault();if(enquiryTrigger.dataset.priority)setChoice('priority',enquiryTrigger.dataset.priority);closeDialog();$('#enquire').scrollIntoView({behavior:reducedMotion()?'instant':'smooth'});return;}
 const previewReview=e.target.closest('[data-review-preview]');if(previewReview){openReview(previewReview);return;}
});
const reducedMotion=()=>window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const menuToggle=$('.menu-toggle'),mainNav=$('#mainNav');
function closeMenu(){mainNav.classList.remove('is-open');document.body.classList.remove('menu-open');menuToggle.setAttribute('aria-expanded','false');menuToggle.setAttribute('aria-label','Open menu');$('.menu-label').textContent='Menu';}
menuToggle.addEventListener('click',()=>{const open=mainNav.classList.toggle('is-open');menuToggle.setAttribute('aria-expanded',String(open));menuToggle.setAttribute('aria-label',open?'Close menu':'Open menu');document.body.classList.toggle('menu-open',open);$('.menu-label').textContent=open?'Close':'Menu';});
$$('a',mainNav).forEach(a=>a.addEventListener('click',closeMenu));
document.addEventListener('click',e=>{if(!e.target.closest('.site-header'))closeMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();closeSectionMenu();}});
const sectionToggle=$('.preview-toggle'),sectionMenu=$('#sectionMenu');
function closeSectionMenu(){sectionMenu.hidden=true;sectionToggle.setAttribute('aria-expanded','false');}
sectionToggle.addEventListener('click',()=>{sectionMenu.hidden=!sectionMenu.hidden;sectionToggle.setAttribute('aria-expanded',String(!sectionMenu.hidden));});
$$('a',sectionMenu).forEach(a=>a.addEventListener('click',closeSectionMenu));
document.addEventListener('click',e=>{if(!e.target.closest('.preview-tools'))closeSectionMenu();});
if('IntersectionObserver'in window){const navObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){$$('.main-nav a').forEach(a=>{if(a.getAttribute('href')==='#'+entry.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});}});},{rootMargin:'-20% 0px -55% 0px'});$$('main>section[id]').forEach(s=>navObserver.observe(s));}

const star=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 2.4 3 6.1 6.7 1-4.9 4.7 1.2 6.7-6-3.2-6 3.2 1.2-6.7L2.3 9.5l6.7-1Z"/></svg>`;

function openReview(trigger){openDialog(`<article class="dialog-review"><div class="google-subline"><img src="assets/google.svg" alt="Google" width="28" height="28"><span class="google-reviews-label">Review preview</span></div><h2 id="dialogTitle" style="margin-top:24px">A more familiar Google review experience.</h2><div class="review-stars" aria-label="Illustrative star styling">${star.repeat(5)}</div><p>This is a layout preview. In the finished site, this space will contain the full, verified customer review from Parkezi’s Google Business Profile.</p><p>No customer name, quote, date or aggregate rating has been invented for this design.</p><a class="google-button" href="https://share.google/VfGvd0vTujh7s6tyS" target="_blank" rel="noopener"><img src="assets/google.svg" alt="" width="19" height="19">Open Parkezi on Google ${icon('arrow')}</a></article>`,trigger);}


const originalDashboard=$('#dashBody')?.innerHTML||'';
const dashboardViews={
 overview:{title:'Car park overview',body:originalDashboard},
 access:{title:'Vehicle access',body:`<table class="dash-table"><thead><tr><th>Group</th><th>Access rule</th><th>Status</th></tr></thead><tbody><tr><td>Staff</td><td>Weekday access</td><td><span class="pill-status">Active</span></td></tr><tr><td>Residents</td><td>Authorised vehicles</td><td><span class="pill-status">Active</span></td></tr><tr><td>Visitors</td><td>Visitor access</td><td><span class="pill-status">Active</span></td></tr></tbody></table><p class="dash-callout">Illustrative access groups. A real demo would show the configuration for your own site.</p>`},
 payments:{title:'Parking payments',body:`<table class="dash-table"><thead><tr><th>Session</th><th>Method</th><th>Status</th></tr></thead><tbody><tr><td>Visitor parking</td><td>Contactless</td><td><span class="pill-status">Paid</span></td></tr><tr><td>Visitor parking</td><td>QR payment</td><td><span class="pill-status">Paid</span></td></tr><tr><td>Hotel patron</td><td>Validation</td><td><span class="pill-status">Validated</span></td></tr></tbody></table><p class="dash-callout">Demo sessions only. No actual transactions are displayed or processed.</p>`},
 reports:{title:'Parking reports',body:`<div class="dash-chart"><div class="dash-chart-top"><strong>Vehicle activity</strong><span>Illustrative data</span></div><div class="bars" style="height:120px">${[35,58,72,89,65,95,78,42,55,69,48,26].map(h=>`<i style="--bar:${h}%"></i>`).join('')}</div><div class="chart-axis"><span>Mon</span><span>Wed</span><span>Sun</span></div></div><p class="dash-callout">Explore parking activity and reporting with your team in a Parkezi demo.</p>`}
};
$$('[data-dashboard]').forEach(b=>b.addEventListener('click',()=>{$$('[data-dashboard]').forEach(x=>x.classList.toggle('is-active',x===b));const v=dashboardViews[b.dataset.dashboard];$('#dashTitle').textContent=v.title;$('#dashBody').innerHTML=v.body;}));
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('is-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('is-visible'),3500);}


const formState={priority:'Paid parking'};
function setChoice(group,value){formState[group]=value;$$(`[data-choice="${group}"]`).forEach(b=>{const selected=b.dataset.value===value;b.classList.toggle('is-selected',selected);b.setAttribute('aria-pressed',String(selected));});$('#formSelection').textContent=formState.priority;}
$$('[data-choice]').forEach(b=>b.addEventListener('click',()=>setChoice(b.dataset.choice,b.dataset.value)));
$('#enquiryForm').addEventListener('submit',e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;const values=new FormData(e.currentTarget);openDialog(`<article class="dialog-system"><p class="eyebrow">Enquiry preview</p><h2 id="dialogTitle">Enquiry preview</h2><p>This is a preview of the enquiry flow. Your details have not been sent.</p><div class="enquiry-summary"><dl><dt>Name</dt><dd>${escapeText([values.get('firstName'),values.get('lastName')].filter(Boolean).join(' '))}</dd><dt>Email</dt><dd>${escapeText(values.get('email'))}</dd><dt>Phone</dt><dd>${escapeText([values.get('dialCode'),values.get('phone')].filter(Boolean).join(' ')||'Not provided')}</dd><dt>Address</dt><dd>${escapeText(values.get('address'))}</dd><dt>Message</dt><dd>${escapeText(values.get('message'))}</dd><dt>Attachments</dt><dd>${escapeText([...values.getAll('attachments')].filter(f=>f?.name).map(f=>f.name).join(', ')||'None')}</dd></dl></div><button class="button button-dark" type="button" data-close-preview>Back to the design ${icon('arrow')}</button></article>`,e.submitter);});
document.addEventListener('click',e=>{if(e.target.closest('[data-close-preview]'))closeDialog();});
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#"]');if(!link||link.hasAttribute('data-product')||link.hasAttribute('data-system')||link.hasAttribute('data-dialog-enquire'))return;const target=document.getElementById(link.hash.slice(1));if(!target)return;e.preventDefault();history.replaceState(null,'',link.hash);target.scrollIntoView({behavior:'instant',block:'start'});});
$('#copyrightYear').textContent=String(new Date().getFullYear());

$('#newsletterPreview').addEventListener('submit',e=>{e.preventDefault();if(e.currentTarget.reportValidity())toast('Newsletter preview only. No subscription has been sent.');});
document.addEventListener('keydown',e=>{if(e.key!=='Tab'||!mainNav.classList.contains('is-open'))return;const controls=[menuToggle,...$$('a,button',mainNav).filter(x=>x.getClientRects().length)];const first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
window.matchMedia('(min-width:721px)').addEventListener('change',e=>{if(e.matches)closeMenu();});

